        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('sapiens.workflow_action_executions') AND c.contype = 'f' AND a.attname = 'workflow_execution_id'
    ) THEN
        ALTER TABLE sapiens.workflow_action_executions ADD CONSTRAINT fk_workflow_action_executions_workflow_execution_id FOREIGN KEY (workflow_execution_id) REFERENCES sapiens.workflow_executions (id) ON DELETE CASCADE ON UPDATE CASCADE NOT VALID;
        BEGIN
            ALTER TABLE sapiens.workflow_action_executions VALIDATE CONSTRAINT fk_workflow_action_executions_workflow_execution_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_workflow_action_executions_workflow_execution_id left NOT VALID: stored rows of sapiens.workflow_action_executions reference missing rows';
        END;
    END IF;
END $$;

